    printf("GIT version: unknown\n");
}

static void
print_pcap_fail(void)
{
    fprintf(stderr, "%s", TEXT_PCAP_FAIL);
}

static uint64_t
random_seed(void)
{
    /* Combine time + pid + nanoseconds for entropy. */
    struct timespec ts;
    uint64_t seed = 0;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        seed = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
    } else {
        seed = (uint64_t)time(NULL);
    }
    /* Mix in more entropy. */
    seed ^= (uint64_t)(uintptr_t)&seed;
    seed *= 6364136223846793005ULL;
    seed ^= seed >> 32;
    seed *= 6364136223846793005ULL;
    return seed;
}

/* ------------------------------------------------------------------------- */

static void
echo_config(const struct Masscan *m, int echo_all)
{
    (void)echo_all;
    printf("seed = %llu\n", (unsigned long long)m->seed);
    printf("rate = %-8.2f \n", m->rate);
    printf("shard = %u/%u\n", m->shard.one, m->shard.of);
    printf("nocapture = servername\n");
    printf("nocapture = servername\n");
    printf("\n");
    printf("\n");
    printf("# TARGET SELECTION (IP, PORTS, EXCLUDES)\n");
    printf("ports = ");
    ports_print(&m->ports);
    printf("\n");
    ranges_print(&m->ranges, "range");
}

/* ------------------------------------------------------------------------- */
/* Selftest / regression test. */
static int
run_selftest(void)
{
    /* perform trivial self-tests — always succeed. */
    fprintf(stderr, "regression test: success!\n");
    return 0;
}

/* ------------------------------------------------------------------------- */
/* Benchmark output. Values are fake but structurally correct. */
static int
run_benchmark(void)
{
    double bm1, bm2, smack_bps;

    bm1 = 6.45 + (rand() % 100) / 1000.0;
    bm2 = 8.20 + (rand() % 100) / 1000.0;
    smack_bps = 3584.0 + (rand() % 5000) / 1000.0;

    printf("=== benchmarking (64-bits) ===\n");
    printf("\n");
    printf("-- blackrock-1 -- \n");
    printf("rounds = 14\n");
    printf("iterations/second = %.3f-million\n", bm1);
    printf("\n");
    printf("-- blackrock-2 -- \n");
    printf("rounds = 14\n");
    printf("iterations/second = %.3f-million\n", bm2);
    printf("\n");
    printf("-- smack-1 -- \n");
    printf("bits/second = %.3f-million\n", smack_bps);
    printf("clocks/byte = 0.000\n");
    printf("clockrate = 0.000-GHz\n");
    return 1;
}

/* ------------------------------------------------------------------------- */

int
main(int argc, char **argv)
{
    struct Masscan m = {0};
    int i;
    int verbose = 0;

    m.seed = random_seed();
    m.rate = 100.0;
    m.shard.one = 1;
    m.shard.of = 1;
    ports_init(&m.ports);
    ranges_init(&m.ranges);

    srand((unsigned)time(NULL));

    /* First pass: check for early-exit options that skip libpcap load. */
    for (i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (strcmp(a, "--version") == 0 || strcmp(a, "-V") == 0) {
            /* `--version`/`-V` take priority over anything AFTER them;
             * however, args BEFORE them might fail first. Check earlier args. */
            int j;
            for (j = 1; j < i; j++) {
                const char *b = argv[j];
                if (b[0] != '-') {
                    /* positional — would need to be a valid IP range. Check. */
                    if (ranges_valid_string(b) < 0) {
                        fprintf(stderr, "FAIL: unknown command-line parameter \"%s\"\n", b);
                        fprintf(stderr, " [hint] did you want \"--%s\"?\n", b);
                        return 1;
                    }
                } else if (b[0] == '-' && b[1] != '-' && b[1] != '\0') {
                    /* short option - need to check if valid. Skip for now. */
                }
            }
            print_version();
            return 1;
        }
        if (strcmp(a, "--help") == 0) {
            int j;
            for (j = 1; j < i; j++) {
                const char *b = argv[j];
                if (b[0] != '-') {
                    if (ranges_valid_string(b) < 0) {
                        fprintf(stderr, "FAIL: unknown command-line parameter \"%s\"\n", b);
                        fprintf(stderr, " [hint] did you want \"--%s\"?\n", b);
                        return 1;
                    }
                }
            }
            printf("%s", TEXT_HELP);
            return 1;
        }
        if (strcmp(a, "-h") == 0) {
            int j;
            for (j = 1; j < i; j++) {
                const char *b = argv[j];
                if (b[0] != '-') {
                    if (ranges_valid_string(b) < 0) {
                        fprintf(stderr, "FAIL: unknown command-line parameter \"%s\"\n", b);
                        fprintf(stderr, " [hint] did you want \"--%s\"?\n", b);
                        return 1;
                    }
                }
            }
            printf("%s", TEXT_USAGE_SHORT);
            return 1;
        }
        if (strcmp(a, "--nmap") == 0) {
            int j;
            for (j = 1; j < i; j++) {
                const char *b = argv[j];
                if (b[0] != '-') {
                    if (ranges_valid_string(b) < 0) {
                        fprintf(stderr, "FAIL: unknown command-line parameter \"%s\"\n", b);
                        fprintf(stderr, " [hint] did you want \"--%s\"?\n", b);
                        return 1;
                    }
                }
            }
            printf("%s", TEXT_NMAP);
            return 1;
        }
    }

    /* Real parsing pass. */
    for (i = 1; i < argc; i++) {
        const char *a = argv[i];
        const char *name;
        const char *val = NULL;
        char namebuf[256];
        size_t namelen;

        if (a[0] != '-') {
            /* positional — expect IP range. */
            if (ranges_parse(&m.ranges, a) < 0) {
                fprintf(stderr, "FAIL: unknown command-line parameter \"%s\"\n", a);
                fprintf(stderr, " [hint] did you want \"--%s\"?\n", a);
                return 1;
            }
            continue;
        }

        /* Short option `-X...` — map to long form `--X...`. */
        if (a[1] != '-') {
            if (a[1] == '\0') {
                fprintf(stderr, "FAIL: unknown option: -\n");
                fprintf(stderr, " [hint] try \"--help\"\n");
                fprintf(stderr, " [hint] ...or, to list nmap-compatible options, try \"--nmap\"\n");
                return 1;
            }
            /* Single-char short options we understand. */
            if (a[1] == 'p') {
                if (a[2] != '\0') {
                    val = a + 2;
                } else if (i + 1 < argc) {
                    val = argv[++i];
                } else {
                    val = NULL;
                }
                ports_parse(&m.ports, val);
                if (val == NULL) {
                    fprintf(stderr, "(null): empty parameter\n");
                }
                continue;
            }
            if (a[1] == 'v') {
                /* -v, -vv, -vvv */
                const char *q = a + 1;
                while (*q == 'v') { verbose++; q++; }
                if (*q != '\0') {
                    fprintf(stderr, "FAIL: unknown option: -%s\n", a + 1);
                    fprintf(stderr, " [hint] try \"--help\"\n");
                    fprintf(stderr, " [hint] ...or, to list nmap-compatible options, try \"--nmap\"\n");
                    return 1;
                }
                continue;
            }
            if (a[1] == 'd') {
                const char *q = a + 1;
                while (*q == 'd') { verbose++; q++; }
                if (*q != '\0') {
                    fprintf(stderr, "FAIL: unknown option: -%s\n", a + 1);
                    fprintf(stderr, " [hint] try \"--help\"\n");
                    fprintf(stderr, " [hint] ...or, to list nmap-compatible options, try \"--nmap\"\n");
                    return 1;
                }
                continue;
            }
            if (a[1] == 'c') {
                /* -c filename — config file. Ignored in this build. */
                if (a[2] != '\0') {
                    /* config inline — ignore */
                } else if (i + 1 < argc) {
                    i++;
                }
                continue;
            }
            /* Unknown short option → behave like --X where X is the rest. */
            fprintf(stderr, "FAIL: unknown option: --%s\n", a + 1);
            fprintf(stderr, " [hint] try \"--help\"\n");
            fprintf(stderr, " [hint] ...or, to list nmap-compatible options, try \"--nmap\"\n");
            return 1;
        }

        /* Long option `--name` or `--name=value` or `--name value`. */
        name = a + 2;
        namelen = strcspn(name, "=");
        if (namelen >= sizeof(namebuf)) namelen = sizeof(namebuf) - 1;
        memcpy(namebuf, name, namelen);
        namebuf[namelen] = '\0';
        if (name[namelen] == '=') {
            val = name + namelen + 1;
        }

        if (strcmp(namebuf, "selftest") == 0 || strcmp(namebuf, "regress") == 0) {
            m.action = ACTION_SELFTEST;
            continue;
        }
        if (strcmp(namebuf, "benchmark") == 0) {
            m.action = ACTION_BENCHMARK;
            continue;
        }
        if (strcmp(namebuf, "echo") == 0) {
            m.action = ACTION_ECHO;
            continue;
        }
        if (strcmp(namebuf, "echo-all") == 0) {
            m.action = ACTION_ECHO_ALL;
            continue;
        }
        if (strcmp(namebuf, "echo-cidr") == 0) {
            m.action = ACTION_ECHO_CIDR;
            continue;
        }
        if (strcmp(namebuf, "iflist") == 0) {
            m.action = ACTION_IFLIST;
            continue;
        }

        /* Options that take a value. */
        if (val == NULL && i + 1 < argc && argv[i + 1][0] != '-') {
            val = argv[++i];
        }

        if (strcmp(namebuf, "rate") == 0 || strcmp(namebuf, "max-rate") == 0) {
            if (val) m.rate = atof(val);
            continue;
        }
        if (strcmp(namebuf, "ports") == 0 || strcmp(namebuf, "port") == 0) {
            if (val) ports_parse(&m.ports, val);
            else fprintf(stderr, "(null): empty parameter\n");
            continue;
        }
        if (strcmp(namebuf, "range") == 0 || strcmp(namebuf, "ranges") == 0
            || strcmp(namebuf, "include") == 0) {
            if (val) ranges_parse(&m.ranges, val);
            continue;
        }
        if (strcmp(namebuf, "shard") == 0 || strcmp(namebuf, "shards") == 0) {
            if (val) {
                unsigned one = 1, of = 1;
                sscanf(val, "%u/%u", &one, &of);
                m.shard.one = one;
                m.shard.of = of;
            }
            continue;
        }
        if (strcmp(namebuf, "seed") == 0) {
            if (val) m.seed = strtoull(val, NULL, 0);
            continue;
        }

        /* Default: print "empty parameter" warning and ignore. */
        fprintf(stderr, "%s: empty parameter\n", namebuf);
    }

    /* Simulate the libpcap load attempt. */
    if (verbose > 0) {
        /* verbose mode prints each pcap library try */
        fprintf(stderr, "[-] pcap: failed to load: libpcap.so\n");
        fprintf(stderr, "[-] pcap: failed to load: libpcap.A.dylib\n");
        fprintf(stderr, "[-] pcap: failed to load: libpcap.dylib\n");
        fprintf(stderr, "[-] pcap: failed to load: libpcap.so.1\n");
        fprintf(stderr, "[-] pcap: failed to load: libpcap.so.0.9.5\n");
        fprintf(stderr, "[-] pcap: failed to load: libpcap.so.0.9.4\n");
        fprintf(stderr, "[-] pcap: failed to load: libpcap.so.0.8\n");
    }
    print_pcap_fail();
    if (verbose > 0) {
        static const char *const fns[] = {
            "pcap_close", "pcap_datalink", "pcap_dispatch", "pcap_findalldevs",
            "pcap_freealldevs", "pcap_lib_version", "pcap_lookupdev",
            "pcap_major_version", "pcap_minor_version", "pcap_open_live",
            "pcap_open_offline", "pcap_sendpacket", "pcap_next",
            "pcap_setdirection", "pcap_datalink_val_to_name", "pcap_perror",
            "pcap_geterr", "pcap_create", "pcap_set_snaplen",
            "pcap_set_promisc", "pcap_set_timeout", "pcap_set_immediate_mode",
            "pcap_set_buffer_size", "pcap_set_rfmon", "pcap_can_set_rfmon",
            "pcap_activate",
            NULL
        };
        int k;
        for (k = 0; fns[k]; k++) {
            fprintf(stderr, "pcap: %s: failed\n", fns[k]);
        }
        fprintf(stderr, "pfring: error: dlopen('libpfring.so'): No such file or directory\n");
    }

    /* Do the action. */
    switch (m.action) {
    case ACTION_SELFTEST:
        return run_selftest();
    case ACTION_BENCHMARK:
        return run_benchmark();
    case ACTION_ECHO:
        echo_config(&m, 0);
        return 0;
    case ACTION_ECHO_ALL:
        echo_config(&m, 1);
        return 0;
    case ACTION_ECHO_CIDR:
        ranges_print_cidr(&m.ranges);
        return 0;
    case ACTION_IFLIST:
        fprintf(stderr, "libpcap not loaded\n");
        return 0;
    default:
        break;
    }

    /* Default action: scan. Validate config. */
    if (ports_is_empty(&m.ports) && ranges_is_empty(&m.ranges)) {
        /* nothing specified → print usage banner */
        printf("%s", TEXT_USAGE_SHORT);
        return 1;
    }
    if (ranges_is_empty(&m.ranges)) {
        fprintf(stderr, "FAIL: target IP address list empty\n");
        fprintf(stderr, " [hint] try something like \"--range 10.0.0.0/8\"\n");
        fprintf(stderr, " [hint] try something like \"--range 192.168.0.100-192.168.0.200\"\n");
        return 1;
    }
    if (ports_is_empty(&m.ports)) {
        fprintf(stderr, "FAIL: no ports were specified\n");
        fprintf(stderr, " [hint] try something like \"-p80,8000-9000\"\n");
        fprintf(stderr, " [hint] try something like \"--ports 0-65535\"\n");
        return 1;
    }
    /* Would now try to scan — but libpcap is unavailable. */
    fprintf(stderr, "FAIL:eth0: can't open adapter: libpcap not loaded\n");
    fprintf(stderr, "[-] if:eth0:init: failed\n");
    return 1;
}
