#include "masscan.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

void
ports_init(struct PortList *p)
{
    p->items = NULL;
    p->count = 0;
    p->cap = 0;
}

static void
ports_reserve(struct PortList *p, size_t n)
{
    if (p->cap >= n) return;
    if (p->cap == 0) p->cap = 8;
    while (p->cap < n) p->cap *= 2;
    p->items = (struct PortRange *)realloc(p->items, p->cap * sizeof(struct PortRange));
}

int
ports_is_empty(const struct PortList *p)
{
    return p->count == 0;
}

/* Parse single token into proto+begin+end. Advances *pp. */
static int
parse_token(const char **pp, int *cur_proto, struct PortRange *out)
{
    const char *p = *pp;
    int proto = *cur_proto;
    long begin, end;
    char *ep;

    /* proto prefix */
    if ((p[0] == 'U' || p[0] == 'u') && p[1] == ':') { proto = 1; p += 2; }
    else if ((p[0] == 'T' || p[0] == 't') && p[1] == ':') { proto = 0; p += 2; }
    else if ((p[0] == 'S' || p[0] == 's') && p[1] == ':') { proto = 2; p += 2; }
    else if ((p[0] == 'O' || p[0] == 'o') && p[1] == ':') { proto = 3; p += 2; }

    while (*p == ' ' || *p == '\t') p++;

    if (!isdigit((unsigned char)*p)) return -1;
    begin = strtol(p, &ep, 10);
    p = ep;
    if (*p == '-') {
        p++;
        if (!isdigit((unsigned char)*p)) return -1;
        end = strtol(p, &ep, 10);
        p = ep;
    } else {
        end = begin;
    }
    if (begin < 0 || end < 0 || begin > 65535 || end > 65535 || begin > end) return -1;

    *cur_proto = proto;
    out->proto = proto;
    out->begin = (unsigned)begin;
    out->end = (unsigned)end;
    *pp = p;
    return 0;
}

/* Compare two PortRange for sort: by (proto, begin). */
static int
cmp_pr(const void *a, const void *b)
