#include "masscan.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

void
ranges_init(struct RangeList *r)
{
    r->items = NULL;
    r->count = 0;
    r->cap = 0;
    r->originals = NULL;
    r->originals_count = 0;
    r->originals_cap = 0;
}

static void
ranges_reserve(struct RangeList *r, size_t n)
{
    if (r->cap >= n) return;
    if (r->cap == 0) r->cap = 8;
    while (r->cap < n) r->cap *= 2;
    r->items = (struct Ipv4Range *)realloc(r->items, r->cap * sizeof(struct Ipv4Range));
}

static void
originals_add(struct RangeList *r, const char *s)
{
    if (r->originals_count >= r->originals_cap) {
        size_t nc = r->originals_cap == 0 ? 8 : r->originals_cap * 2;
        r->originals = (char **)realloc(r->originals, nc * sizeof(char *));
        r->originals_cap = nc;
    }
    r->originals[r->originals_count++] = strdup(s);
}

int
ranges_is_empty(const struct RangeList *r)
{
    return r->count == 0;
}

/* Parse dotted-quad into uint32. Returns 0 on success. */
static int
parse_ipv4(const char *s, const char **ep, uint32_t *out)
{
    uint32_t ip = 0;
    int i;
    for (i = 0; i < 4; i++) {
        long v;
        char *nep;
        if (!isdigit((unsigned char)*s)) return -1;
        v = strtol(s, &nep, 10);
        if (v < 0 || v > 255) return -1;
        ip = (ip << 8) | (uint32_t)v;
        s = nep;
        if (i < 3) {
            if (*s != '.') return -1;
            s++;
        }
    }
    if (ep) *ep = s;
    *out = ip;
    return 0;
}

/* Parse a single IP range string. Supported forms:
 *   A.B.C.D
 *   A.B.C.D/N   (0<=N<=32)
 *   A.B.C.D-E.F.G.H
 */
static int
parse_range_string(const char *s, uint32_t *pbegin, uint32_t *pend)
{
    uint32_t begin, end;
    const char *p;
    if (parse_ipv4(s, &p, &begin) < 0) return -1;
    if (*p == '\0') {
        *pbegin = begin; *pend = begin;
        return 0;
    }
    if (*p == '/') {
        long n;
        char *ep;
        p++;
        if (!isdigit((unsigned char)*p)) return -1;
        n = strtol(p, &ep, 10);
        if (n < 0 || n > 32) return -1;
        p = ep;
        if (*p != '\0') return -1;
        if (n == 0) {
            *pbegin = 0; *pend = 0xFFFFFFFFu;
        } else {
            uint32_t mask = (uint32_t)(0xFFFFFFFFu << (32 - n));
            *pbegin = begin & mask;
            *pend = *pbegin | (~mask);
        }
        return 0;
    }
    if (*p == '-') {
        p++;
        if (parse_ipv4(p, &p, &end) < 0) return -1;
        if (*p != '\0') return -1;
        if (end < begin) return -1;
        *pbegin = begin;
        *pend = end;
        return 0;
    }
    return -1;
}

int
ranges_valid_string(const char *s)
{
    uint32_t b, e;
    return parse_range_string(s, &b, &e);
}

static int
cmp_r(const void *a, const void *b)
{
    const struct Ipv4Range *A = a, *B = b;
    if (A->begin != B->begin) return (A->begin < B->begin) ? -1 : 1;
    if (A->end != B->end) return (A->end < B->end) ? -1 : 1;
    return 0;
}

static void
ranges_merge(struct RangeList *r)
{
    size_t i, j;
    if (r->count == 0) return;
    qsort(r->items, r->count, sizeof(r->items[0]), cmp_r);
    j = 0;
    for (i = 1; i < r->count; i++) {
        if (r->items[i].begin <= r->items[j].end
            || (r->items[j].end != 0xFFFFFFFFu
                && r->items[i].begin == r->items[j].end + 1)) {
            if (r->items[i].end > r->items[j].end)
                r->items[j].end = r->items[i].end;
        } else {
            j++;
            r->items[j] = r->items[i];
        }
    }
    r->count = j + 1;
}

int
ranges_parse(struct RangeList *r, const char *s)
{
    const char *p = s;
    while (*p) {
        const char *start = p;
        char buf[128];
        size_t n;
        uint32_t b, e;
        while (*p && *p != ',') p++;
        n = (size_t)(p - start);
        if (n >= sizeof(buf)) return -1;
        memcpy(buf, start, n);
        buf[n] = '\0';
        if (n > 0) {
            if (parse_range_string(buf, &b, &e) < 0) return -1;
            ranges_reserve(r, r->count + 1);
            r->items[r->count].begin = b;
            r->items[r->count].end = e;
            r->count++;
            originals_add(r, buf);
        }
        if (*p == ',') p++;
    }
    ranges_merge(r);
    return 0;
}

static void
print_ipv4(uint32_t ip)
{
    printf("%u.%u.%u.%u",
        (ip >> 24) & 0xFF, (ip >> 16) & 0xFF,
        (ip >> 8) & 0xFF, ip & 0xFF);
}

void
ranges_print(const struct RangeList *r, const char *keyword)
{
    size_t i;
    for (i = 0; i < r->count; i++) {
        uint32_t b = r->items[i].begin;
        uint32_t e = r->items[i].end;
        printf("%s = ", keyword);
        if (b == e) {
            print_ipv4(b);
        } else if (b == 0 && e == 0xFFFFFFFFu) {
            print_ipv4(0);
            printf("/0");
        } else {
            /* Try to express as CIDR. */
            uint32_t span = e - b + 1;
            int bits;
            if ((span & (span - 1)) == 0 && (b & (span - 1)) == 0) {
                bits = 0;
                while (span > 1) { bits++; span >>= 1; }
                print_ipv4(b);
                printf("/%d", 32 - bits);
            } else {
                print_ipv4(b);
                printf("-");
                print_ipv4(e);
            }
        }
        printf("\n");
    }
}

